python3 -c "
import csv
# Get unique codebook entries per product (deduplicated by standard_label)
for prod in ['P1_POWER', 'P2_CTRL', 'P3_RF']:
    with open(f'/app/data/codebook_{prod}.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        entries = {}
        for row in reader:
            label = row['standard_label']
            if label not in entries:
                entries[label] = row
        print(f'\n=== {prod}: {len(entries)} unique labels ===')
        for label, row in entries.items():
            print(f'  {row[\"code\"]} | {label} | stations={row[\"station_scope\"]} | kw={row[\"keywords_examples\"]}')
"
